import json,sys
d=json.load(sys.stdin)
for f in d['data']['__schema']['mutationType']['fields']:
    for a in f['args']:
        tn = a['type']
        name = tn.get('name') or (tn.get('ofType') or {}).get('name')
        if name and 'IssueUpdate' in name:
            print(f['name'], '->', a['name'], name)
"

